import random
from collections import Counter, defaultdict

story = """the robot found a key . the robot found a door . the robot helped the girl .
the girl found the robot . the robot learned to read . the girl helped the robot .
the robot found a map . the girl learned to code . the robot learned to draw ."""
words = story.split()
model = defaultdict(Counter)
for a, b, c in zip(words, words[1:], words[2:]):
    model[(a, b)][c] += 1


def probabilities(context, temperature):
    counts = model[context]
    scaled = {w: n ** (1 / temperature) for w, n in counts.items()}
    total = sum(scaled.values())
    return {w: s / total for w, s in scaled.items()}


print("next word after 'the robot':")
for t in (1.0, 0.3, 3.0):
    probs = probabilities(("the", "robot"), t)
    print(f"  temperature {t}: " + ", ".join(f"{w} {p:.0%}" for w, p in sorted(probs.items(), key=lambda kv: -kv[1])))


def generate(temperature, seed, length=10):
    rng = random.Random(seed)
    out = ["the", "robot"]
    while len(out) < length and (out[-2], out[-1]) in model:
        probs = probabilities((out[-2], out[-1]), temperature)
        out.append(rng.choices(list(probs), weights=list(probs.values()))[0])
    return " ".join(out)


print()
for t in (0.3, 3.0):
    for seed in (1, 2):
        print(f"temperature {t}, seed {seed}: {generate(t, seed)}")

